package com.securevault.controller;
import com.securevault.repository.UserRepository;import com.securevault.service.SessionService;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/sessions") @CrossOrigin(origins="http://localhost:5173") public class SessionController{private final UserRepository users;private final SessionService service;public SessionController(UserRepository u,SessionService s){users=u;service=s;}@GetMapping public Object list(Authentication a){return service.list(users.findByEmail(a.getName()).orElseThrow());}@DeleteMapping("/{id}")public Map<String,Object> revoke(@PathVariable Long id,Authentication a){service.revoke(id,users.findByEmail(a.getName()).orElseThrow());return Map.of("message","Session revoked");}}
